INSERT INTO public.field_help (help_key, title, purpose, examples, format_notes, extra_notes, module_code)
VALUES
  ('public.accounts.default_methodology', 'Default methodology', 'The delivery approach new portfolios, programmes and projects start with.', '- Hybrid', NULL, NULL, 'admin_settings'),
  ('public.accounts.allow_project_methodology_override', 'Allow methodology override', 'Tick to let a portfolio, programme or project choose a different approach from the organisation default.', '- Ticked', NULL, NULL, 'admin_settings'),
  ('public.accounts.form_bulk_approve_max', 'Form bulk approve limit', 'The most form submissions an approver can approve in one go.', '- 25', NULL, NULL, 'admin_settings'),
  ('public.accounts.project_invitation_expiry_days', 'Default expiry (days)', 'How many days a project invitation stays valid before the person must be invited again.', '- 7', NULL, 'Each invitation can still choose a different expiry when it is sent.', 'admin_settings'),
  ('public.ai_settings.ai_enabled', 'AI features on', 'Tick to let people in your organisation use the AI assistant and AI drafting.', '- Ticked', NULL, NULL, 'admin_settings'),
  ('public.ai_settings.conversation_retention_months', 'Keep conversations for (months)', 'How long AI conversations are kept before they are deleted.', '- 12', NULL, NULL, 'admin_settings'),
  ('public.ai_settings.audit_retention_months', 'Keep usage records for (months)', 'How long records of AI use are kept for audit.', '- 24', NULL, NULL, 'admin_settings'),
  ('public.ai_settings.report_language_code', 'Language for AI-drafted reports', 'The language the AI writes report drafts in.', '- English', NULL, NULL, 'admin_settings'),
  ('public.draft_expiry_config.entity_type', 'Entity type', 'The kind of record this expiry rule applies to. Leave blank to use the project type instead.', '- Risk', NULL, NULL, 'admin_settings'),
  ('public.draft_expiry_config.project_type_id', 'Project type', 'The project type this expiry rule applies to. Leave blank to use the entity type instead.', '- Infrastructure', NULL, NULL, 'admin_settings'),
  ('public.draft_expiry_config.expiry_days', 'Expiry days', 'Days a saved draft is kept before it is removed.', '- 30', NULL, NULL, 'admin_settings'),
  ('public.draft_expiry_config.warning_days', 'Warning days', 'Days before expiry when the owner is warned that the draft will be removed.', '- 3', NULL, NULL, 'admin_settings'),
  ('public.email_configurations.api_key', 'Resend API key', 'The secret key from your Resend account that lets the system send email for you.', '- re_xxxxxxxx', NULL, 'Leave blank when editing to keep the current key.', 'admin_settings'),
  ('public.email_configurations.from_email', 'From email', 'The address emails are sent from. It must be on a domain you have verified with the email provider.', '- projects@company.example', NULL, NULL, 'admin_settings'),
  ('public.email_configurations.from_name', 'From name', 'The sender name people see in their inbox.', '- Example Freight Ltd Projects', NULL, NULL, 'admin_settings'),
  ('public.email_configurations.reply_to_email', 'Reply-to email', 'Where replies go, if not to the from address.', '- pmo@company.example', NULL, NULL, 'admin_settings'),
  ('public.email_configurations.smtp_host', 'SMTP host', 'The address of your mail server.', '- smtp.company.example', NULL, NULL, 'admin_settings'),
  ('public.email_configurations.smtp_port', 'Port', 'The port your mail server listens on.', '- 587', 'Usually 587 (TLS) or 465 (SSL).', NULL, 'admin_settings'),
  ('public.email_configurations.smtp_username', 'Username', 'The account name used to sign in to the mail server.', '- projects@company.example', NULL, NULL, 'admin_settings'),
  ('public.email_configurations.smtp_password', 'Password', 'The password or app key for the mail server account.', '- An app password from your mail provider', NULL, 'Leave blank when editing to keep the current one.', 'admin_settings'),
  ('public.extra_seat_purchases.quantity', 'Number of seats', 'How many extra user seats to buy for the project.', '- 10', NULL, NULL, 'admin_settings'),
  ('public.organisation_branding.app_display_name', 'App display name', 'The name shown in the header in place of the product name.', '- Example Freight Projects', 'Up to 100 characters.', NULL, 'admin_settings'),
  ('public.organisation_branding.app_tagline', 'Tagline', 'A short line shown under the app name.', '- Delivering on time, every time', 'Up to 200 characters.', NULL, 'admin_settings'),
  ('public.organisation_branding.base_font_size', 'Base font size', 'The text size used across the app for your organisation.', '- Medium', NULL, NULL, 'admin_settings'),
  ('public.roles.role_name', 'Role name (internal)', 'The fixed system name of the role, used behind the scenes.', '- qa_test_lead', NULL, NULL, 'admin_settings'),
  ('public.roles.display_name', 'Role name', 'The role name people see.', '- QA Test Lead', NULL, NULL, 'admin_settings'),
  ('public.roles.description', 'Description', 'What people in this role do.', '- Plans and leads testing for the project.', NULL, NULL, 'admin_settings'),
  ('public.roles.role_skills', 'Required skills', 'The skills someone needs to fill this role.', '- Test planning; defect management', NULL, NULL, 'admin_settings'),
  ('public.roles.role_level', 'Level', 'How senior the role is. Higher numbers are more senior.', '- 3', NULL, NULL, 'admin_settings'),
  ('public.roles.industry_category_id', 'Industry', 'The industry this role belongs to. Leave blank if it applies to all industries.', '- Construction & Engineering', NULL, NULL, 'admin_settings'),
  ('public.roles.is_governance_only', 'Oversight-only', 'Tick for roles that only watch progress, such as a board member or sponsor. They get the read-only Governance Dashboard.', '- Ticked', NULL, NULL, 'admin_settings'),
  ('public.roles.menu_layout_key', 'Menu based on', 'Which standard sidebar the role starts from.', '- Team member menu', NULL, NULL, 'admin_settings'),
  ('public.roles.start_from_bundle', 'Start from a bundle', 'Copy the menu items of a saved bundle to this role. Later changes to the bundle do not change the role.', '- Finance team pages', NULL, NULL, 'admin_settings'),
  ('public.org_menu_bundles.bundle_name', 'Bundle name', 'A name for this set of menu items.', '- Finance team pages', NULL, NULL, 'admin_settings'),
  ('public.org_menu_bundles.description', 'Description', 'Which roles the bundle is meant for.', '- Pages finance staff need on every project.', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.invitation_type', 'Invitation type', 'Whether you are inviting someone to a project or as a PMO administrator.', '- Project', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.role_id', 'Role', 'The role the person will have once they accept.', '- Project Manager', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.project_id', 'Project', 'The project the person is invited to.', '- Warehouse Upgrade', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.company_name', 'Organisation / company', 'The organisation the invitation comes from. It is filled in for you.', '- Example Freight Ltd', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.invited_first_name', 'First name', 'The first name of the person you are inviting.', '- Sam', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.invited_last_name', 'Surname', 'The surname of the person you are inviting.', '- Example', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.email', 'Email address', 'Where the invitation is sent.', '- project.manager@company.example', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.invitation_expires_at', 'Invitation expires after', 'How long the person has to accept before the link stops working.', '- Organisation default (7 days)', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.invitation_message', 'Message', 'An optional note shown in the invitation email.', '- Welcome to the team. Our kick-off is on Monday.', NULL, NULL, 'admin_settings'),
  ('public.organisation_invitations.assign_user_id', 'User', 'The existing user to give the role to.', '- Head of Finance', NULL, NULL, 'admin_settings'),
  ('public.project_assignments.project_id', 'Project', 'The project to give the person a role on.', '- Warehouse Upgrade', NULL, NULL, 'admin_settings'),
  ('public.project_assignments.user_id', 'User', 'The person to give the role to.', '- Project Coordinator', NULL, NULL, 'admin_settings'),
  ('public.project_assignments.role_id', 'Role', 'The role they will have on that project.', '- Team Member', NULL, NULL, 'admin_settings'),
  ('public.project_timesheet_settings.standard_daily_hours', 'Standard daily hours', 'Normal working hours in a day on this project.', '- 7.5', NULL, 'Tick Override first to change it for this project; otherwise the organisation default applies.', 'admin_settings'),
  ('public.project_timesheet_settings.max_overtime_per_day', 'Max overtime / day', 'The most overtime hours someone can log in one day.', '- 2', NULL, 'Tick Override first to change it for this project; otherwise the organisation default applies.', 'admin_settings'),
  ('public.project_timesheet_settings.max_overtime_per_week', 'Max overtime / week', 'The most overtime hours someone can log in one week.', '- 8', NULL, 'Tick Override first to change it for this project; otherwise the organisation default applies.', 'admin_settings'),
  ('public.project_timesheet_settings.working_days', 'Standard working days', 'The days people normally work on this project.', '- Mon to Fri', NULL, 'Tick Override first to change it for this project; otherwise the organisation default applies.', 'admin_settings'),
  ('public.system_settings.max_manager_assignments', 'Maximum assignments per manager', 'The most portfolios, programmes or projects one manager can be assigned at the same time.', '- 5', NULL, NULL, 'admin_settings'),
  ('public.users.full_name', 'Full name', 'Your name as others see it in the app.', '- Sam Example', NULL, NULL, 'admin_settings'),
  ('public.users.email', 'Email', 'The address you sign in with and get notifications at.', '- sam.example@company.example', NULL, NULL, 'admin_settings'),
  ('public.users.bio', 'Bio', 'A short note about you for your team.', '- Project manager for the London depot programme.', NULL, NULL, 'admin_settings'),
  ('public.users.current_password', 'Current password', 'Your password now, to confirm it is you.', '- Your current password', NULL, NULL, 'admin_settings'),
  ('public.users.new_password', 'New password', 'The password you want to use from now on.', '- A long phrase you have not used before', 'At least 8 characters.', NULL, 'admin_settings'),
  ('public.users.confirm_password', 'Confirm new password', 'Type the new password again to check it.', '- The same new password', NULL, NULL, 'admin_settings')
